  s+=r('','display:flex;align-items:center;gap:16%;padding:0;')+r('>.pan',face+'width:42%;min-height:40%;position:relative;display:flex;flex-direction:column;justify-content:center;gap:var(--gap-sm);padding:var(--gap);text-align:center;transform:translateY(calc(var(--tilt)*-.15cqh));')+r('>.pan:nth-child(2)','transform:translateY(calc(var(--tilt)*.15cqh));')+r('>.pan>.name','font-size:clamp(var(--type-16),2.8cqw,var(--type-24));font-weight:var(--name-weight);line-height:var(--name-line);color:'+accent+';')+r('>.pan>.item','font-size:var(--type-14);line-height:var(--body-line);')+r('>.pan.on','border-top:5px solid var(--a1);')+r('>.fulcrum','position:absolute;left:40%;right:40%;bottom:6%;height:24%;background:var(--a1);color:var(--a1-on);clip-path:polygon(50% 0,100% 100%,0 100%);display:flex;align-items:flex-end;justify-content:center;padding-bottom:var(--gap-sm);font-size:var(--type-12);line-height:var(--label-line);')+r('::before','content:"";position:absolute;left:8%;right:8%;top:67%;border-top:3px solid var(--a1);transform:rotate(calc(var(--tilt)*.12deg));z-index:-1;')
